#!/usr/bin/env bash
#
# TRU_GPU_CREDIT_01_SOURCE_PATCH.sh
#
# SOURCE ONLY. Patches one file:  src/my_gpu_miner.cpp
# Does NOT compile. Does NOT touch the node, chain, wallet or config.
#
#     cd ~/NEW_TRU           && bash ./TRU_GPU_CREDIT_01_SOURCE_PATCH.sh
#     cd ~/projects/NEW_TRU  && bash ./TRU_GPU_CREDIT_01_SOURCE_PATCH.sh
#     cd ~/TRU-release-clean && bash ./TRU_GPU_CREDIT_01_SOURCE_PATCH.sh
#
# THE BUG (GPU-CREDIT-01)
#   Two sites decided hash-work credit using the PROCESS-WIDE g_found flag:
#
#       if (!foundFlag && !g_found.load()) { creditCompletedHashWork(...); }
#
#   foundFlag alone is already correct. The OpenCL kernel aborts on its own
#   device flag:
#
#       if(atomic_cmpxchg(foundFlag, 0, 0) != 0) return;
#
#   so a kernel that exited early reads back foundFlag != 0 and is denied
#   credit by !foundFlag. The extra g_found test denied credit to kernels
#   that ran a FULL sweep and found nothing, purely because some other
#   kernel on some other device had won in the meantime.
#
#   At short block times g_found is set most of the time, so almost all
#   honest work scored zero:
#       "GPU-1 completed. Kernels launched: 3, completed: 0, creditedHashes: 0"
#       "Mining completed. Found: 1, Credited hashes: 0, Rate: 0.000000 H/s"
#
#   g_sessionHashes then stayed 0. That is the counter the keepalive
#   reporter uses, so the node published hashRate 0, and the explorer -
#   which counts only reports with hashRate > 0 - showed no active miners
#   while both GPUs ran at 100% utilisation.
#
# THE FIX
#   Both credit sites now test this kernel's own foundFlag only. The two
#   solution-claim sites, which legitimately use g_found to decide who
#   submits the block, are left exactly as they were.
#
#   This is a COUNTER fix. No mining work was ever lost; blocks already
#   mined were real. Only the accounting and the reported rate were wrong.
#
# Re-running is safe: an already-patched tree is detected and left alone.
#
set -Eeuo pipefail
REPO="${TRU_REPO:-$PWD}"
TARGET="${REPO}/src/my_gpu_miner.cpp"
STAMP="$(date +%Y%m%d-%H%M%S)"
SCRATCH="$(mktemp -d)"
BACKUP="${REPO}/src/my_gpu_miner.cpp.pre-gpu-credit-01.${STAMP}.bak"
EMBEDDED_SHA256="5bc3db226bd17a2366ce68a504a7c32c6153e7ff707661260a68ffab04fb2abf"
PRE_NEW_TRU_SHA256="9a6645dff3492fe9b11b55ab379e640f46fd6adfc307df667526518f8020e107"
POST_NEW_TRU_SHA256="68cafea7c65fffe9457d9e37b7a3624e117f291b51965469392c31913ace25e5"
PRE_CLEAN_SHA256="271bba6641c88794359c00b99c43ce629683c15b93962d567a0d8a1a7659dee9"
POST_CLEAN_SHA256="3f069b43bb1cc8e4e33bf83d579258aa4f7a2c7d2e8a1332d284d0a0bab5d98e"
say() { printf '%s\n' "$*"; }
sha_of() { sha256sum "$1" | awk '{print $1}'; }
die() { printf '\nFAIL: %s\n' "$*" >&2; exit 1; }
cleanup() { rm -rf "$SCRATCH"; }
trap cleanup EXIT

say "=============================================================="
say " TRU_GPU_CREDIT_01   hash-work credit denied by global g_found"
say " repo: ${REPO}"
say "=============================================================="

say ""
say "[0] PACKAGE SELF-CHECK"
command -v python3 >/dev/null 2>&1 || die "python3 required"
sed -n "/^#__BEGIN_B64__$/,/^#__END_B64__$/p" "$0" \
    | sed -e '1d' -e '$d' -e 's/^#//' | base64 -d > "${SCRATCH}/bundle.bin"
[ "$(sha_of "${SCRATCH}/bundle.bin")" = "$EMBEDDED_SHA256" ] \
    || die "embedded payload sha mismatch"
say "    EMBEDDED_PIN=PASS"

say ""
say "[1] LOCATE TARGET"
[ -f "$TARGET" ] || die "no src/my_gpu_miner.cpp under ${REPO}
Run from a TRU repo root, or set TRU_REPO=/path/to/repo."
[ -L "$TARGET" ] && die "src/my_gpu_miner.cpp is a symlink; refusing"
[ -w "$TARGET" ] || die "src/my_gpu_miner.cpp is not writable by $(id -un).
If root-owned:  sudo chown -R \$(id -un):\$(id -gn) ${REPO}"
say "    target: src/my_gpu_miner.cpp"

say ""
say "[2] PREHASH GATE"
actual="$(sha_of "$TARGET")"
if [ "$actual" = "$POST_NEW_TRU_SHA256" ] || [ "$actual" = "$POST_CLEAN_SHA256" ]; then
    say ""
    say "ALREADY PATCHED - this tree is at the GPU-CREDIT-01 post hash."
    say "Nothing to do."
    exit 0
elif [ "$actual" = "$PRE_NEW_TRU_SHA256" ]; then
    VARIANT="new_tru"; EXPECT_POST="$POST_NEW_TRU_SHA256"
    say "    VARIANT=NEW_TRU (patch labels present)"
elif [ "$actual" = "$PRE_CLEAN_SHA256" ]; then
    VARIANT="clean";   EXPECT_POST="$POST_CLEAN_SHA256"
    say "    VARIANT=RELEASE_CLEAN (labels stripped)"
else
    die "src/my_gpu_miner.cpp matches neither supported tree.
  found      ${actual}
  NEW_TRU    ${PRE_NEW_TRU_SHA256}
  clean      ${PRE_CLEAN_SHA256}
DO NOT edit a pin. Send me your current file instead."
fi
say "    PREHASH_PIN=PASS"

say ""
say "[3] BACKUP"
cp -p "$TARGET" "$BACKUP"
say "    ${BACKUP}"

say ""
say "[4] VERIFY CANDIDATE"
python3 - "$SCRATCH" "$VARIANT" << 'INNER_PY'
import pathlib, sys
scratch, variant = pathlib.Path(sys.argv[1]), sys.argv[2]
raw = (scratch / "bundle.bin").read_text(encoding="utf-8")
parts = {}
for chunk in raw.split("====VARIANT:")[1:]:
    name, rest = chunk.split("====\n", 1)
    parts[name] = rest
if variant not in parts:
    sys.stderr.write("bundle lacks variant %s\n" % variant); raise SystemExit(1)
body = parts[variant]
(scratch / "my_gpu_miner.cpp").write_text(body, encoding="utf-8")
live = "\n".join(l for l in body.splitlines() if not l.strip().startswith("//"))
if "!foundFlag && !g_found.load()" in live:
    sys.stderr.write("a credit site is still gated on g_found\n"); raise SystemExit(1)
if live.count("if (!foundFlag) {") != 2:
    sys.stderr.write("expected exactly 2 corrected credit sites\n"); raise SystemExit(1)
if live.count("if (foundFlag && !g_found.load())") != 2:
    sys.stderr.write("the 2 solution-claim sites must be unchanged\n"); raise SystemExit(1)
if body.count("{") != body.count("}"):
    sys.stderr.write("braces unbalanced\n"); raise SystemExit(1)
print("    CREDIT_SITES_FIXED=2")
print("    SOLUTION_CLAIM_SITES_UNCHANGED=2")
print("    BRACES_BALANCED=PASS")
INNER_PY

say ""
say "[5] INSTALL"
cp "${SCRATCH}/my_gpu_miner.cpp" "$TARGET"
post="$(sha_of "$TARGET")"
if [ "$post" != "$EXPECT_POST" ]; then
    cp -p "$BACKUP" "$TARGET"
    die "posthash mismatch after write; original restored"
fi
say "    INSTALLED_PIN=PASS"

say ""
say "=============================================================="
say "TRU_GPU_CREDIT_01=PATCHED  variant=${VARIANT}"
say ""
say "PRE  ${actual}"
say "POST ${post}"
say ""
say "CREDIT_DECIDED_BY=per-kernel foundFlag"
say "SOLUTION_CLAIM_PATH=unchanged"
say "CONSENSUS_CHANGE=NO"
say "SOURCE_ONLY=YES (nothing compiled)"
say ""
if [ -f "${REPO}/${TRU_BUILD_DIR:-build-native}/CMakeCache.txt" ]; then
    say "To make it live - stop the miner (the node can keep running):"
    say "  cmake --build ${TRU_BUILD_DIR:-build-native} --target tru_miner -j\$(nproc)"
    say "  restart the GPU miner"
    say ""
    say "Then confirm credit is flowing:"
    say "  grep 'Credited hashes' build-native/bin/gpu_miner.log | tail -3"
    say "  curl -s http://127.0.0.1:8001/api/miner-reports | grep -o '\"hashRate\":[0-9]*'"
else
    say "No build directory here - staging tree. Commit and push."
fi
say ""
say "Revert:  cp -p ${BACKUP} ${TARGET}"
say "=============================================================="
exit 0

